        const dansVue = function (p) {
          return !!p.boite && p.boite[0] + p.boite[2] / 2 > 0 && p.boite[0] - p.boite[2] / 2 < cv.width &&
            p.boite[1] + p.boite[3] / 2 > 0 && p.boite[1] - p.boite[3] / 2 < cv.height;
        };
