          tailles: montres.filter(function (p) { return p.icone; }).map(function (p) { return [p.boite[2], p.boite[3]]; })
            .filter(function (t) { return Math.abs(t[0] - 28) > 1 || Math.abs(t[1] - 28) > 1; }).slice(0, 3),
