      const q = function (s) { const el = document.querySelector("#kta-vue3d " + s); return el ? el.getBoundingClientRect() : null; };
      const c = function (r) { return r ? [Math.round(r.left + r.width / 2), Math.round(r.top + r.height / 2)] : null; };
